    this.next = null
  }
}

class LinkedList {
  constructor(value) {
    this.head = null
    this.tail = null
    this.length = 0
    if (value !== undefined) {
      const firstNode = new Node(value)
      this.head = firstNode
      this.tail = this.head
      this.length = 1
    }
  }

  push(value) {
    const nodeToAdd = new Node(value)
    if (!this.head) {
      this.head = nodeToAdd
      this.tail = nodeToAdd
    } else {
      this.tail.next = nodeToAdd
      this.tail = nodeToAdd
    }
    this.length++
    return this
  }

  shift() {
    // 1. if the list is empty, return undefined
    // 2. oldHead points to the first node
    // 3. head moves to the next node
    // 4. oldHead's next becomes null, to cut it off
    // 5. subtract 1 from length
    // 6. if length is now 0, tail becomes null too
    // 7. return oldHead
  }

  // our helper: the values from head to tail, as an array
  toArray() {
    const values = []
    let current = this.head
    while (current !== null) {
      values.push(current.value)
      current = current.next
    }
    return values
